import json
import itertools

def solve_puzzle():
    houses = [1, 2, 3, 4, 5]

    names = ["Arnold", "Eric", "Bob", "Peter", "Alice"]
    smoothies = ["desert", "watermelon", "lime", "cherry", "dragonfruit"]
    nationalities = ["german", "swede", "norwegian", "dane", "brit"]

    # Utility to find the house index for a given value in a mapping of {house: value}
    def house_of_value(mapping, value):
        for h, v in mapping.items():
            if v == value:
                return h
        return None

    # Generate smoothie arrangements:
    # - Dragonfruit is in the second house.
    # - Watermelon is in the third house.
    # - Desert is not in the fifth house.
    smoothie_candidates = []
    remaining_smoothies = [s for s in smoothies if s not in ("dragonfruit", "watermelon")]
    for perm in itertools.permutations(remaining_smoothies):
        smap = {2: "dragonfruit", 3: "watermelon", 1: perm[0], 4: perm[1], 5: perm[2]}
        if smap[5] == "desert":
            continue  # Desert smoothie not in the fifth house.
        smoothie_candidates.append(smap)

    # Generate nationality arrangements:
    # - Alice is Norwegian and Alice is in the third house => Norwegian in third house.
    nationality_candidates = []
    remaining_nationalities = [n for n in nationalities if n != "norwegian"]
    for perm in itertools.permutations(remaining_nationalities):
        nmap = {3: "norwegian", 1: perm[0], 2: perm[1], 4: perm[2], 5: perm[3]}
        nationality_candidates.append(nmap)

    # Generate name arrangements:
    # - Alice is in the third house.
    # - Peter is not in the first house.
    name_candidates = []
    remaining_names = [n for n in names if n != "Alice"]
    for perm in itertools.permutations(remaining_names):
        nmap = {3: "Alice", 1: perm[0], 2: perm[1], 4: perm[2], 5: perm[3]}
        if nmap[1] == "Peter":
            continue  # Peter is not in the first house.
        name_candidates.append(nmap)

    solutions = []

    for smap in smoothie_candidates:
        # Apply constraints that involve smoothies and nationalities
        for natmap in nationality_candidates:
            # Clue 4: The Dane and the British person are next to each other.
            dane_house = house_of_value(natmap, "dane")
            brit_house = house_of_value(natmap, "brit")
            if dane_house is None or brit_house is None:
                continue
            if abs(dane_house - brit_house) != 1:
                continue

            # Clue 6: The Swedish person is somewhere to the left of the Dragonfruit smoothie lover.
            swede_house = house_of_value(natmap, "swede")
            dragon_house = house_of_value(smap, "dragonfruit")
            if swede_house is None or dragon_house is None:
                continue
            if not (swede_house < dragon_house):
                continue

            # Clue 7: There are two houses between the Lime drinker and the Dane.
            lime_house = house_of_value(smap, "lime")
            if lime_house is None:
                continue
            if abs(lime_house - dane_house) != 3:
                continue

            # Clue 11: The Watermelon smoothie lover is in the third house.
            if house_of_value(smap, "watermelon") != 3:
                continue

            for namemap in name_candidates:
                # Clue 8: Bob is the Dane.
                if house_of_value(namemap, "Bob") != dane_house:
                    continue

                # Clue 9 and 10: Alice is the Norwegian in the third house.
                if house_of_value(namemap, "Alice") != 3:
                    continue
                if house_of_value(natmap, "norwegian") != 3:
                    continue

                # Clue 1: The Dragonfruit smoothie lover is somewhere to the left of Eric.
                eric_house = house_of_value(namemap, "Eric")
                if not (dragon_house < eric_house):
                    continue

                # Clue 5: The Desert smoothie lover is not in the fifth house. (already ensured in smoothie generation)
                if smap[5] == "desert":
                    continue

                # Clue 3: Peter is not in the first house. (ensured in name generation but double-check)
                if namemap[1] == "Peter":
                    continue

                solutions.append((namemap, smap, natmap))

    # Ensure we found exactly one solution
    if len(solutions) != 1:
        raise ValueError(f"Expected exactly one solution, found {len(solutions)}")

    namemap, smap, natmap = solutions[0]

    header = ["House", "Name", "smoothie", "nationality"]
    rows = []
    for h in sorted(houses):
        rows.append([str(h), namemap[h], smap[h], natmap[h]])

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
